module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply reset
    task apply_reset;
        begin
            areset = 1'b1;
            x = 1'b0;
            @(posedge clk);
            @(posedge clk);
            areset = 1'b0;
            @(posedge clk);
        end
    endtask

    // Task to test a sequence
    // Takes an array/stream of input bits representing a binary number (LSB first)
    // and checks the 2's complement output bit by bit.
    task test_sequence(input [7:0] data, input integer length);
        integer i;
        reg [7:0] expected_z;
        reg [8:0] temp_val;
        begin
            // Compute expected 2's complement software-side for verification
            // 2's complement of X is (~X + 1)
            temp_val = -data; // Verilog handles two's complement negation naturally for vectors

            // Apply reset before each test vector sequence
            apply_reset();

            // Drive inputs on negative edge or just after positive edge to sample correctly
            for (i = 0; i < length; i = i + 1) begin
                x = data[i];
                @(posedge clk);
                #1; // small delay for output to settle

                if (z !== temp_val[i]) begin
                    $display("Time %0t: Mismatch! input_seq=0x%h, bit_idx=%0d, x=%b, expected_z=%b, got_z=%b",
                             $time, data, i, data[i], temp_val[i], z);
                    errors = errors + 1;
                end
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        #12;

        // Test Case 1: Number 0 (binary: 0) -> 2's comp is 0
        test_sequence(8'b00000000, 4);

        // Test Case 2: Number 1 (binary: 1, 0, 0, 0 ...) -> LSB first: 1
        // 2's comp of 1 is -1 (all 1s)
        test_sequence(8'b00000001, 4);

        // Test Case 3: Number 3 (binary: 1, 1, 0, 0 -> 3 in decimal)
        // 2's comp of 3 is -3 (binary: 1, 0, 1, 1 ...)
        test_sequence(8'b00000011, 4);

        // Test Case 4: Number 5 (binary: 1, 0, 1, 0 -> 5 in decimal)
        // 2's comp of 5 is -5 (binary: 1, 1, 0, 1 ...)
        test_sequence(8'b00000101, 4);

        // Test Case 5: Asynchronous reset test mid-operation
        apply_reset();
        x = 1'b1; @(posedge clk);
        #1;
        if (z !== 1'b1) begin errors = errors + 1; end

        // Assert reset asynchronously
        areset = 1'b1;
        #2;
        if (z !== 1'b0) begin errors = errors + 1; end // depending on async behavior, check reset state if applicable
        areset = 1'b0;
        @(posedge clk);

        // Final result evaluation
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
